/// @brief Error codes reported by the NFC API.
/// @since_tizen 2.3
/// @ingroup CAPI_NETWORK_NFC_MANAGER_MODULE
abstract class nfc_error_e {
  /// < Successful
  static const int NFC_ERROR_NONE = 0;

  /// < Out of memory
  static const int NFC_ERROR_OUT_OF_MEMORY = -12;

  /// < Operation failed
  static const int NFC_ERROR_OPERATION_FAILED = -29491199;

  /// < Invalid parameter
  static const int NFC_ERROR_INVALID_PARAMETER = -22;

  /// < Invalid NDEF message
  static const int NFC_ERROR_INVALID_NDEF_MESSAGE = -29491198;

  /// < Invalid record type
  static const int NFC_ERROR_INVALID_RECORD_TYPE = -29491197;

  /// < Timeout error, no answer
  static const int NFC_ERROR_TIMED_OUT = -1073741823;

  /// < Previous operation is not finished still busy
  static const int NFC_ERROR_DEVICE_BUSY = -16;

  /// < no device
  static const int NFC_ERROR_NO_DEVICE = -29491196;

  /// < NFC is not activated
  static const int NFC_ERROR_NOT_ACTIVATED = -29491195;

  /// < Not supported
  static const int NFC_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Already activated
  static const int NFC_ERROR_ALREADY_ACTIVATED = -29491194;

  /// < Already deactivated
  static const int NFC_ERROR_ALREADY_DEACTIVATED = -29491193;

  /// < Read only tag
  static const int NFC_ERROR_READ_ONLY_NDEF = -29491192;

  /// < No enough space on tag
  static const int NFC_ERROR_NO_SPACE_ON_NDEF = -29491191;

  /// < No NDEF Message on Tag
  static const int NFC_ERROR_NO_NDEF_MESSAGE = -29491190;

  /// < Not NDEF format Tag
  static const int NFC_ERROR_NOT_NDEF_FORMAT = -29491189;

  /// <  Restricted by access control
  static const int NFC_ERROR_SECURITY_RESTRICTED = -29491188;

  /// < Restricted by Smack
  static const int NFC_ERROR_PERMISSION_DENIED = -13;

  /// <  The state is wrong
  static const int NFC_ERROR_ILLEGAL_STATE = -29491187;

  /// < NFC is not initialized
  static const int NFC_ERROR_NOT_INITIALIZED = -29491186;

  /// < Tag is not supported
  static const int NFC_ERROR_TAG_NOT_SUPPORTED = -29491185;

  /// < AID already registered (@b Since: 2.3.1)
  static const int NFC_ERROR_AID_ALREADY_REGISTERED = -29491184;
}

